<template>
  <div class="page-shell kb-page">
    <PageHero title="知识库" description="汇聚遗址公园相关学术文献、研究报告与政策资料，支持语义检索、知识关联和规范引用。" :image="portalHero" compact>
      <template #actions><el-button @click="showGraphDialog=true"><el-icon><Share /></el-icon>知识图谱</el-button><el-button @click="$router.push('/bibliometrics')"><el-icon><DataAnalysis /></el-icon>计量分析</el-button></template>
    </PageHero>

    <section class="kb-toolbar section-card">
      <el-input v-model="searchText" placeholder="搜索文献标题、关键词、作者、摘要、DOI 等" clearable @keyup.enter="doSearch"><template #prefix><el-icon><Search /></el-icon></template></el-input>
      <el-button type="primary" @click="doSearch">搜索</el-button>
      <el-tag v-if="searchMode" size="small" :type="searchMode==='semantic'?'success':'info'" effect="plain">{{ searchMode==='semantic'?'向量语义':'关键词' }}</el-tag>
      <el-select v-model="filterType" clearable placeholder="文献类型" @change="doSearch"><el-option v-for="type in documentTypes" :key="type" :label="type" :value="type" /></el-select>
      <el-upload v-if="auth.isLoggedIn" :auto-upload="false" :limit="1" accept=".pdf,.docx,.doc,.txt,.md" :on-change="handleFileChange" :show-file-list="false"><el-button type="success"><el-icon><Upload /></el-icon>上传文献</el-button></el-upload>
      <el-dropdown @command="handleToolCommand"><el-button>更多工具 <el-icon><ArrowDown /></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="review"><el-icon><Document /></el-icon>生成综述</el-dropdown-item><el-dropdown-item command="reindex"><el-icon><RefreshRight /></el-icon>重建向量索引</el-dropdown-item><el-dropdown-item command="lint" divided><el-icon><Warning /></el-icon>知识库体检</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
    </section>

    <div v-if="uploading" class="upload-progress section-card"><el-alert :title="uploadStatus" type="info" :closable="false"/><el-progress :percentage="uploadProgress" :stroke-width="10" :status="uploadProgress===100?'success':undefined"/><small v-if="uploadProgress<100">大文件处理中，请勿关闭页面。</small></div>

    <div class="kb-results-bar"><div><strong>共 {{ total }} 条结果</strong><span v-if="searchMode">当前使用{{ searchMode==='semantic'?'语义向量':'关键词' }}检索</span></div><div><span>排序：</span><button class="active" type="button">相关性</button><button type="button">发表时间</button><button type="button">被引量</button></div></div>

    <div class="kb-content-layout">
      <main>
        <StatusState v-if="loading" type="loading" title="正在加载文献" />
        <StatusState v-else-if="loadError" type="error" title="文献列表加载失败" :description="loadError" action-label="重新加载" @action="loadList" />
        <StatusState v-else-if="!literature.length" type="empty" title="暂无文献" description="知识库有内容后会在这里展示；不会使用演示文献填充。" />
        <div v-else class="kb-list">
          <article v-for="lit in literature" :key="lit.id" class="lit-card" @click="showDetail(lit)">
            <div class="lit-type-block"><el-icon><Document /></el-icon><span>{{ lit.doc_type||'文献' }}</span></div>
            <div class="lit-card__content"><h2>{{ lit.title }}</h2><p class="lit-authors">{{ authorText(lit) }}</p><p class="lit-source">{{ lit.journal||'来源未录入' }} · {{ lit.year||'年份未知' }}</p><p class="lit-abstract">{{ abstractText(lit.abstract) }}</p><div class="lit-tags"><span v-for="tag in (lit.keywords||[]).slice(0,5)" :key="tag">{{ tag }}</span></div></div>
            <div class="lit-card__meta"><span>{{ lit.citation_count?`被引 ${lit.citation_count}`:'暂无引用数据' }}</span><div><el-button size="small" text type="primary" @click.stop="copyCitation(lit)"><el-icon><CopyDocument /></el-icon>引用</el-button><el-button v-if="auth.isAdmin" size="small" text type="danger" @click.stop="deleteLit(lit.id)">删除</el-button></div></div>
          </article>
        </div>
        <div v-if="total>pageSize" class="pagination"><el-pagination v-model:current-page="page" :page-size="pageSize" :total="total" layout="prev, pager, next" @current-change="loadList"/></div>
      </main>

      <aside class="kb-sidebar">
        <section class="section-card"><div class="section-card__header"><div><h2>快速工具</h2><p>基于现有知识库能力。</p></div></div><div class="kb-tools"><button type="button" @click="showGraphDialog=true"><el-icon><Share /></el-icon><span><strong>知识图谱</strong><small>探索知识关联网络</small></span></button><button type="button" @click="$router.push('/bibliometrics')"><el-icon><DataAnalysis /></el-icon><span><strong>计量分析</strong><small>分析文献研究趋势</small></span></button><button type="button" @click="showReviewDialog=true"><el-icon><Document /></el-icon><span><strong>生成综述</strong><small>基于已有文献生成</small></span></button><button type="button" @click="doLint"><el-icon><Warning /></el-icon><span><strong>知识库体检</strong><small>检查内容完整性</small></span></button></div></section>
        <section class="section-card"><div class="section-card__header"><div><h2>精选合集</h2><p>来自当前检索结果。</p></div></div><div v-if="literature.length" class="kb-collections"><button v-for="lit in literature.slice(0,4)" :key="lit.id" type="button" @click="showDetail(lit)"><span>{{ lit.doc_type||'文献' }}</span><strong>{{ lit.title }}</strong><small>{{ lit.year||'年份未知' }}</small></button></div><el-empty v-else description="暂无合集内容"/></section>
        <section class="section-card"><div class="section-card__header"><div><h2>热门标签</h2><p>由当前结果关键词汇总。</p></div></div><div v-if="popularTags.length" class="popular-tags"><button v-for="tag in popularTags" :key="tag" type="button" @click="searchText=tag;doSearch()">{{ tag }}</button></div><el-empty v-else description="暂无关键词"/></section>
      </aside>
    </div>

    <el-dialog v-model="detailVisible" :title="detail?.title" width="min(860px,94vw)" top="4vh"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="年份">{{ detail.year||'—' }}</el-descriptions-item><el-descriptions-item label="类型">{{ detail.doc_type||'—' }}</el-descriptions-item><el-descriptions-item label="期刊/来源" :span="2">{{ detail.journal||'—' }}</el-descriptions-item><el-descriptions-item label="作者" :span="2">{{ authorText(detail) }}</el-descriptions-item><el-descriptions-item label="关键词" :span="2"><el-tag v-for="tag in detail.keywords||[]" :key="tag" size="small">{{ tag }}</el-tag></el-descriptions-item><el-descriptions-item label="基金">{{ detail.funding||'—' }}</el-descriptions-item><el-descriptions-item label="方法论">{{ detail.methodology||'—' }}</el-descriptions-item><el-descriptions-item label="摘要" :span="2">{{ detail.abstract||'暂无摘要' }}</el-descriptions-item><el-descriptions-item label="核心论点" :span="2">{{ detail.core_argument||'—' }}</el-descriptions-item></el-descriptions><div class="citation-box"><el-input v-model="citationText" readonly type="textarea" :rows="2"/><div><el-button size="small" type="primary" @click="copyToClipboard(citationText)">复制引用</el-button><el-radio-group v-model="citeStyle" size="small" @change="loadCitation"><el-radio-button value="gbt7714">GB/T 7714</el-radio-button><el-radio-button value="apa">APA</el-radio-button><el-radio-button value="mla">MLA</el-radio-button></el-radio-group></div></div><div v-if="detail.citations_from?.length" class="detail-relations"><h3>引用的文献</h3><p v-for="item in detail.citations_from" :key="item.title">{{ item.author }} ({{ item.year }}). {{ item.title }}</p></div><div v-if="detail.relations?.length" class="detail-relations"><h3>知识关联</h3><p v-for="item in detail.relations" :key="item.target_title"><el-tag :type="relationTagType(item.type)" size="small">{{ relationLabel(item.type) }}</el-tag>{{ item.target_title }} — {{ item.explanation }}</p></div></template></el-dialog>

    <el-dialog v-model="showGraphDialog" title="文献知识图谱" width="95vw" top="2vh" destroy-on-close @opened="renderGraph"><div class="graph-dialog-tools"><span><i></i>文献</span><span><i></i>关键词</span><small>滚轮缩放 · 拖拽移动 · 点击高亮关联</small></div><div ref="graphContainer" class="literature-graph"></div></el-dialog>
    <el-dialog v-model="showReviewDialog" title="生成文献综述" width="min(900px,94vw)" top="4vh"><el-input v-model="reviewTopic" placeholder="综述主题（可选）"><template #prepend>主题</template></el-input><el-button type="primary" :loading="reviewLoading" class="review-button" @click="generateReview"><el-icon><Document /></el-icon>AI 生成综述</el-button><div v-if="reviewResult" class="review-content" v-html="renderMarkdown(reviewResult)"></div></el-dialog>
    <el-dialog v-model="showLintDialog" title="知识库体检" width="min(700px,94vw)" top="5vh"><template v-if="lintResult"><el-alert :title="lintResult.summary" :type="lintResult.issues?.length?'warning':'success'" :closable="false"/><div v-for="(issue,index) in lintResult.issues||[]" :key="index" class="lint-item"><el-tag :type="issue.level==='warning'?'danger':'info'" size="small">{{ issue.level==='warning'?'警告':'提示' }}</el-tag><span>{{ issue.message }}</span></div><el-empty v-if="!lintResult.issues?.length" description="知识库运行良好，未发现问题"/></template></el-dialog>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import api from '@/utils/api'
import { renderMarkdown } from '@/utils/markdown'
import { useAuthStore } from '@/stores/auth'
import PageHero from '@/components/portal/PageHero.vue'
import StatusState from '@/components/common/StatusState.vue'
import portalHero from '@/assets/images/portal-hero.webp'
const auth=useAuthStore();const documentTypes=['期刊论文','学位论文','会议论文','政策报告','著作'];const searchText=ref('');const filterType=ref('');const searchMode=ref('');const literature=ref([]);const total=ref(0);const page=ref(1);const pageSize=ref(12);const loading=ref(false);const loadError=ref('');const uploading=ref(false);const uploadProgress=ref(0);const uploadStatus=ref('');const detail=ref(null);const detailVisible=ref(false);const citationText=ref('');const citeStyle=ref('gbt7714');const showGraphDialog=ref(false);const graphContainer=ref(null);const showReviewDialog=ref(false);const reviewTopic=ref('');const reviewLoading=ref(false);const reviewResult=ref('');const showLintDialog=ref(false);const lintResult=ref(null);let graphChart=null;let graphResizeHandler=null
const popularTags=computed(()=>{const counts={};literature.value.flatMap(item=>item.keywords||[]).forEach(tag=>{counts[tag]=(counts[tag]||0)+1});return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([tag])=>tag)})
onMounted(loadList);onBeforeUnmount(()=>{if(graphResizeHandler)window.removeEventListener('resize',graphResizeHandler);graphChart?.dispose()})
async function loadList(){loading.value=true;loadError.value='';try{const params={page:page.value,page_size:pageSize.value};if(searchText.value)params.keyword=searchText.value;if(filterType.value)params.doc_type=filterType.value;const res=await api.get('/knowledge/list',{params,silent:true});literature.value=res.data.items||[];total.value=res.data.total||0}catch(e){loadError.value=e.response?.data?.detail||'请检查知识库服务后重试。'}finally{loading.value=false}}
async function doSearch(){page.value=1;if(searchText.value.trim()){try{const res=await api.get('/knowledge/search',{params:{q:searchText.value,limit:20},silent:true});searchMode.value=res.data.mode||'sql';if(res.data.results?.length){literature.value=res.data.results;total.value=res.data.results.length;return}}catch{}}searchMode.value='';loadList()}
async function handleFileChange(file){uploading.value=true;uploadProgress.value=15;uploadStatus.value='正在上传文件…';try{const form=new FormData();form.append('file',file.raw);uploadProgress.value=35;uploadStatus.value='正在提取元数据与识别引用关系…';const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),600000);let response;try{response=await fetch('/api/knowledge/upload',{method:'POST',headers:{Authorization:`Bearer ${localStorage.getItem('token')||''}`},body:form,signal:controller.signal})}finally{clearTimeout(timeout)}if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.detail||`服务器错误 (${response.status})`)}const data=await response.json();uploadProgress.value=100;uploadStatus.value='入库成功';ElMessage.success(`文献已入库：${data.title}`);setTimeout(loadList,500)}catch(e){ElMessage.error(e.name==='AbortError'?'上传处理超时，请稍后刷新查看':e.message||'上传失败')}finally{uploading.value=false}}
async function showDetail(lit){try{detail.value=(await api.get(`/knowledge/detail/${lit.id}`,{silent:true})).data;detailVisible.value=true;loadCitation()}catch{ElMessage.error('加载详情失败')}}async function loadCitation(){if(!detail.value)return;try{citationText.value=(await api.get(`/knowledge/cite/${detail.value.id}`,{params:{style:citeStyle.value},silent:true})).data.citation}catch{citationText.value=''}}async function copyCitation(lit){try{const text=(await api.get(`/knowledge/cite/${lit.id}`,{params:{style:'gbt7714'},silent:true})).data.citation;await copyToClipboard(text)}catch{ElMessage.error('获取引用失败')}}async function copyToClipboard(text){try{await navigator.clipboard.writeText(text);ElMessage.success('已复制')}catch{ElMessage.error('复制失败，请手动复制')}}async function deleteLit(id){try{await ElMessageBox.confirm('确定删除该文献？','确认');await api.delete(`/knowledge/delete/${id}`);ElMessage.success('已删除');loadList()}catch(e){if(e!=='cancel')ElMessage.error('删除失败')}}
async function handleToolCommand(command){if(command==='review')showReviewDialog.value=true;if(command==='reindex')await doReindex();if(command==='lint')await doLint()}async function doReindex(){try{const res=await api.post('/knowledge/reindex');ElMessage.success(res.data.success?`已重建索引：${res.data.indexed} 篇文献`:`索引失败：${res.data.error}`)}catch{ElMessage.error('重建索引失败')}}async function doLint(){try{lintResult.value=(await api.get('/knowledge/lint',{silent:true})).data;showLintDialog.value=true}catch{ElMessage.error('健康检查失败')}}async function generateReview(){reviewLoading.value=true;reviewResult.value='';try{const res=await api.post('/knowledge/review/generate',null,{params:{topic:reviewTopic.value||'',max_lits:20},timeout:180000});reviewResult.value=res.data.review||'生成失败';ElMessage.success(`综述生成完成，引用 ${res.data.lits_referenced} 篇文献`)}catch(e){ElMessage.error(e.response?.data?.detail||'综述生成失败')}finally{reviewLoading.value=false}}
async function renderGraph(){if(!graphContainer.value)return;try{const {nodes=[],edges=[]}=(await api.get('/knowledge/graph',{silent:true})).data;if(!nodes.length){ElMessage.info('当前暂无可展示的知识图谱');return}if(graphChart)graphChart.dispose();const echarts=await import('echarts');graphChart=echarts.init(graphContainer.value);const seen=new Set();const mappedNodes=nodes.filter(node=>!seen.has(node.id)&&seen.add(node.id)).map(node=>node.type==='keyword'?{id:node.id,name:node.label,symbolSize:Math.min(12+(node.count||1)*3,44),category:1,symbol:'diamond'}:{id:node.id,name:node.label,symbolSize:node.symbolSize||24,category:0});const colors={cites:'#cbd5e1',contradicts:'#ef4444',supports:'#22c55e',complements:'#22c55e',shares_topic:'#f59e0b',has_keyword:'#c7d2fe'};graphChart.setOption({tooltip:{},legend:{data:['文献','关键词'],bottom:8},series:[{type:'graph',layout:'force',data:mappedNodes,links:edges.map(edge=>({source:edge.source,target:edge.target,lineStyle:{color:colors[edge.type]||'#d1d5db',opacity:.55}})),roam:true,draggable:true,categories:[{name:'文献',itemStyle:{color:'#2563eb'}},{name:'关键词',itemStyle:{color:'#22c55e'}}],label:{show:mappedNodes.length<35,fontSize:10,position:'bottom'},force:{repulsion:300,edgeLength:[70,220],gravity:.08},emphasis:{focus:'adjacency'}}]});graphResizeHandler=()=>graphChart?.resize();window.addEventListener('resize',graphResizeHandler)}catch{ElMessage.error('图谱渲染失败')}}
function authorText(item){return(item.authors||[]).map(author=>author.name+(author.institution?`（${author.institution}）`:'' )).join('、')||'作者未录入'}function abstractText(text){return text?`${text.slice(0,190)}${text.length>190?'…':''}`:'暂无摘要'}function relationTagType(type){return{supports:'success',contradicts:'danger',complements:'primary',shares_topic:'warning'}[type]||'info'}function relationLabel(type){return{supports:'支持',contradicts:'矛盾',complements:'互补',shares_topic:'同主题',cites:'引用'}[type]||type}
</script>

<style scoped lang="scss">
.kb-toolbar{padding:16px;display:grid;grid-template-columns:minmax(260px,1fr) auto auto 150px auto auto;gap:8px;align-items:center}.upload-progress{padding:18px}.upload-progress .el-progress{margin-top:12px}.upload-progress small{display:block;margin-top:7px;color:var(--text-tertiary)}.kb-results-bar{display:flex;align-items:center;justify-content:space-between;gap:16px}.kb-results-bar>div{display:flex;align-items:center;gap:12px}.kb-results-bar span{color:var(--text-tertiary);font-size:11px}.kb-results-bar button{border:0;background:none;color:var(--text-secondary);cursor:pointer;font-size:11px}.kb-results-bar button.active{color:var(--brand-600);font-weight:650}.kb-content-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:16px}.kb-list{display:grid;gap:10px}.lit-card{padding:16px;display:grid;grid-template-columns:86px minmax(0,1fr) 120px;gap:16px;border:1px solid var(--border);border-radius:14px;background:#fff;box-shadow:var(--shadow-soft);cursor:pointer;transition:border-color .2s ease,transform .2s ease}.lit-card:hover{transform:translateY(-2px);border-color:var(--brand-100)}.lit-type-block{height:92px;display:grid;place-items:center;align-content:center;gap:7px;border-radius:12px;color:var(--brand-600);background:var(--brand-50)}.lit-type-block .el-icon{font-size:26px}.lit-type-block span{font-size:10px}.lit-card__content h2{margin:0;font-size:15px;line-height:1.5}.lit-authors,.lit-source,.lit-abstract{margin:5px 0 0;color:var(--text-secondary);font-size:11px;line-height:1.6}.lit-source{color:var(--text-tertiary)}.lit-abstract{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.lit-tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.lit-tags span{padding:4px 7px;border-radius:999px;color:var(--text-secondary);background:var(--surface-soft);font-size:9px}.lit-card__meta{display:flex;flex-direction:column;align-items:flex-end;justify-content:space-between;color:var(--text-tertiary);font-size:10px}.lit-card__meta>div{display:flex}.pagination{display:flex;justify-content:center;margin-top:20px}.kb-sidebar{display:grid;align-content:start;gap:14px}.kb-sidebar>section{padding:18px}.kb-tools{display:grid;grid-template-columns:1fr 1fr;gap:8px}.kb-tools button{padding:11px;display:flex;gap:8px;border:1px solid var(--border);border-radius:10px;color:var(--brand-600);background:#fff;cursor:pointer;text-align:left}.kb-tools button>span{display:grid;color:var(--text-primary)}.kb-tools strong{font-size:10px}.kb-tools small{margin-top:3px;color:var(--text-tertiary);font-size:8px}.kb-collections{display:grid}.kb-collections button{padding:10px 0;display:grid;border:0;border-bottom:1px solid var(--border);background:none;cursor:pointer;text-align:left}.kb-collections span{color:var(--brand-600);font-size:8px}.kb-collections strong{margin-top:3px;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.kb-collections small{margin-top:3px;color:var(--text-tertiary);font-size:8px}.popular-tags{display:flex;gap:6px;flex-wrap:wrap}.popular-tags button{padding:6px 9px;border:0;border-radius:999px;color:var(--text-secondary);background:var(--surface-soft);cursor:pointer;font-size:9px}.citation-box{margin-top:16px}.citation-box>div{margin-top:8px;display:flex;justify-content:space-between;gap:10px}.detail-relations{margin-top:16px}.detail-relations h3{font-size:14px}.detail-relations p{padding:7px 0;border-bottom:1px solid var(--border);color:var(--text-secondary);font-size:12px;line-height:1.6}.detail-relations .el-tag{margin-right:6px}.graph-dialog-tools{display:flex;gap:14px;align-items:center;margin-bottom:10px;font-size:11px}.graph-dialog-tools span{display:flex;align-items:center;gap:5px}.graph-dialog-tools i{width:9px;height:9px;border-radius:50%;background:var(--brand-600)}.graph-dialog-tools span:nth-child(2) i{background:var(--green-500)}.graph-dialog-tools small{margin-left:auto;color:var(--text-tertiary)}.literature-graph{width:100%;height:72vh;border-radius:12px;background:var(--surface-soft)}.review-button{margin-top:12px}.review-content{max-height:60vh;margin-top:16px;padding:20px;overflow:auto;border:1px solid var(--border);border-radius:12px;background:var(--surface-soft)}.lint-item{padding:9px 0;display:flex;align-items:flex-start;gap:8px;border-bottom:1px solid var(--border);font-size:12px}
@media(max-width:1080px){.kb-toolbar{grid-template-columns:minmax(240px,1fr) auto auto 150px}.kb-content-layout{grid-template-columns:1fr}.kb-sidebar{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.kb-toolbar{grid-template-columns:1fr auto}.kb-toolbar .el-select{grid-column:1/-1}.kb-results-bar{align-items:flex-start;flex-direction:column}.kb-content-layout{grid-template-columns:1fr}.lit-card{grid-template-columns:64px 1fr}.lit-type-block{height:76px}.lit-card__meta{grid-column:1/-1;flex-direction:row;align-items:center}.kb-sidebar{grid-template-columns:1fr}.citation-box>div{align-items:flex-start;flex-direction:column}.graph-dialog-tools small{display:none}}
</style>
